  limits: {memory: 2Gi, cpu: 2000m}

ChromaDB:
  requests: {memory: 1Gi, cpu: 500m}
  limits: {memory: 2Gi, cpu: 1000m}

Neo4j:
  requests: {memory: 2Gi, cpu: 1000m}
  limits: {memory: 4Gi, cpu: 2000m}
